function afficher() { document.querySelector("#reste").textContent = reste; }
afficher();

solution:
const capacite = Number(document.querySelector("#stock").dataset.capacite);
let reste = capacite;
function afficher() {
  document.querySelector("#reste").textContent = reste;
  document.querySelector("#sortis").textContent = capacite - reste;
}
afficher();
document.querySelector("#prendre").addEventListener("click", function () { if (reste > 0) { reste = reste - 1; } afficher(); });
document.querySelector("#rendre").addEventListener("click", function () { if (reste < capacite) { reste = reste + 1; } afficher(); });

