solution:
let total = 0;
const objectif = Number(document.querySelector("#defi").dataset.objectif);
function rendre() {
  document.querySelector("#points").textContent = total;
  document.querySelector("#etat").textContent = total >= objectif ? "Objectif atteint" : "En cours";
}
function relier(bouton) { bouton.addEventListener("click", function () { total = total + Number(bouton.dataset.points); rendre(); }); }
relier(document.querySelector("#lecture"));
relier(document.querySelector("#jardin"));
document.querySelector("#recommencer").addEventListener("click", function () { total = 0; rendre(); });
rendre();

